using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;
public static class AgentWorldFourForge {
 const string D="Assets/Resources/WorldFour/";static Material stone,iron,bronze,glow,glass;static int serial;
 static Material Material(string name,Color color,float metallic,float smooth,bool emission=false){string p=D+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",smooth);if(emission){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*2.5f);}else{string tp=D+name+"-surface.png";var tex=new Texture2D(256,256);var pixels=new Color[256*256];for(int y=0;y<256;y++)for(int x=0;x<256;x++){float n=Mathf.PerlinNoise(x*.14f,y*.14f)*.25f+Mathf.PerlinNoise(x*.033f+10,y*.033f)*.2f;float scratch=Mathf.Pow(Mathf.PerlinNoise(x*.8f,y*.025f),8)*.4f;float value=.57f+n-scratch;pixels[y*256+x]=new Color(value,value,value,1);}tex.SetPixels(pixels);tex.Apply();File.WriteAllBytes(tp,tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);AssetDatabase.ImportAsset(tp);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(tp));m.SetTextureScale("_BaseMap",Vector2.one*2);}EditorUtility.SetDirty(m);return m;}
 static GameObject Root(string name)=>new GameObject(name);
 static void Box(GameObject root,string name,Vector3 p,Vector3 scale,Material mat,Vector3 e=default,bool solid=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root.transform,false);g.transform.localPosition=p;g.transform.localScale=scale;g.transform.localEulerAngles=e;g.GetComponent<Renderer>().sharedMaterial=mat;if(!solid)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
 static Mesh Lathe(Vector2[] profile,int segments=32){var v=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();for(int j=0;j<profile.Length;j++)for(int i=0;i<=segments;i++){float a=2*Mathf.PI*i/segments;v.Add(new Vector3(Mathf.Cos(a)*profile[j].x,profile[j].y,Mathf.Sin(a)*profile[j].x));uv.Add(new Vector2(i/(float)segments,j/(float)(profile.Length-1)));}for(int j=0;j<profile.Length-1;j++)for(int i=0;i<segments;i++){int a=j*(segments+1)+i,b=a+segments+1;tr.AddRange(new[]{a,b,a+1,a+1,b,b+1});}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tr,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();return mesh;}
 static void Shape(GameObject root,string name,Vector3 p,Vector2[] profile,Material mat,Vector3 e=default){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.transform.localPosition=p;g.transform.localEulerAngles=e;var mesh=Lathe(profile);string path=D+root.name+"-"+name+"-"+(serial++)+".asset";AssetDatabase.CreateAsset(mesh,path);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;}
 static void Collider(GameObject root,Vector3 size,Vector3 center){var c=root.AddComponent<BoxCollider>();c.size=size;c.center=center;}
 static void Save(GameObject g){PrefabUtility.SaveAsPrefabAsset(g,D+g.name+".prefab");UnityEngine.Object.DestroyImmediate(g);}
 static void Ring(GameObject g,string name,Vector3 p,float radius,float tube,Material mat,Vector3 rotation=default){var profile=new Vector2[13];for(int i=0;i<13;i++){float a=i*Mathf.PI*2/12;profile[i]=new Vector2(radius+Mathf.Cos(a)*tube,Mathf.Sin(a)*tube);}Shape(g,name,p,profile,mat,rotation);}
 public static string Run(){Directory.CreateDirectory(D);AssetDatabase.Refresh();serial=0;
 stone=Material("Basalto estratificado",new Color(.18f,.20f,.24f),.05f,.22f);iron=Material("Hierro azulado",new Color(.15f,.20f,.23f),.82f,.4f);bronze=Material("Bronce gastado",new Color(.43f,.24f,.10f),.75f,.36f);glow=Material("Ascua cautiva",new Color(1,.24f,.045f),0,.5f,true);glass=Material("Memoria azul",new Color(.075f,.38f,.5f),.3f,.7f,true);
 var g=Root("Floor");Box(g,"Losa basáltica",new Vector3(0,.175f,0),new Vector3(4,.35f,4),stone,solid:true);foreach(int s in new[]{-1,1})Box(g,"Junta de latón",new Vector3(s*1.94f,.352f,0),new Vector3(.045f,.012f,4),bronze);Save(g);
 g=Root("Wall");Box(g,"Muro de escoria",new Vector3(0,3,.08f),new Vector3(4,6,.55f),stone,solid:true);foreach(int s in new[]{-1,1}){Box(g,"Costilla inclinada",new Vector3(s*1.65f,3,-.32f),new Vector3(.24f,6.2f,.5f),iron,new Vector3(0,0,s*8));Box(g,"Remache",new Vector3(s*1.5f,1.8f,-.65f),new Vector3(.16f,.16f,.1f),bronze);}for(int i=0;i<3;i++)Box(g,"Banda estructural",new Vector3(0,.4f+i*2.5f,-.28f),new Vector3(4,.15f,.22f),iron);Save(g);
 g=Root("Rail");foreach(int s in new[]{-1,1})Box(g,"Poste",new Vector3(s*1.8f,.7f,0),new Vector3(.14f,1.4f,.14f),iron);for(int i=0;i<2;i++)Box(g,"Baranda",new Vector3(0,.55f+i*.65f,0),new Vector3(4,.10f,.12f),bronze);Collider(g,new Vector3(4,1.35f,.2f),Vector3.up*.675f);Save(g);
 g=Root("Furnace");Shape(g,"Crisol",Vector3.zero,new[]{new Vector2(1.5f,0),new Vector2(1.6f,.3f),new Vector2(1.35f,.5f),new Vector2(1.25f,3.4f),new Vector2(.7f,4.2f),new Vector2(.65f,6.4f),new Vector2(.8f,6.5f),new Vector2(.5f,6.5f),new Vector2(.45f,4)},iron);for(int i=0;i<3;i++)Ring(g,"Aro",Vector3.up*(.7f+i*1.5f),1.3f-i*.04f,.1f,bronze);for(int i=0;i<5;i++)Box(g,"Ranura incandescente",new Vector3(-.6f+i*.3f,1.7f,-1.25f),new Vector3(.10f,1.8f,.08f),glow);Collider(g,new Vector3(3,6.5f,3),Vector3.up*3.25f);Save(g);
 g=Root("Bell");Shape(g,"Campana rota",Vector3.zero,new[]{new Vector2(1.7f,0),new Vector2(1.68f,.18f),new Vector2(1.2f,.6f),new Vector2(.85f,2),new Vector2(.7f,2.5f),new Vector2(.12f,2.7f),new Vector2(.08f,2.5f),new Vector2(.55f,2.32f),new Vector2(.68f,1.85f),new Vector2(1.05f,.5f),new Vector2(1.52f,.05f),new Vector2(1.7f,0)},bronze);Shape(g,"Badajo",new Vector3(0,-.15f,0),new[]{new Vector2(.01f,0),new Vector2(.28f,.15f),new Vector2(.12f,.6f),new Vector2(.06f,2.2f)},iron);Ring(g,"Ojo de suspensión",Vector3.up*2.9f,.22f,.065f,iron,new Vector3(90,0,0));Save(g);
 g=Root("Chain");for(int i=0;i<12;i++)Ring(g,"Eslabón",Vector3.up*i*.3f,.19f,.045f,iron,new Vector3(90,i%2*90,0));Save(g);
 g=Root("RibArch");foreach(int s in new[]{-1,1}){Box(g,"Pata",new Vector3(s*3,2.5f,0),new Vector3(.45f,5,.65f),iron,solid:true);for(int i=0;i<4;i++)Box(g,"Nervio",new Vector3(s*(2.8f-i*.72f),5.15f+i*.48f,0),new Vector3(1.05f,.30f,.65f),bronze,new Vector3(0,0,-s*34));}Save(g);
 g=Root("Pipe");Shape(g,"Conducto",Vector3.zero,new[]{new Vector2(.32f,0),new Vector2(.32f,4)},iron,new Vector3(90,0,0));Ring(g,"Brida",Vector3.zero,.38f,.08f,bronze,new Vector3(90,0,0));Save(g);
 g=Root("Archive");Box(g,"Armario de nombres",new Vector3(0,1.8f,0),new Vector3(3.2f,3.6f,.9f),iron,solid:true);for(int x=0;x<4;x++)for(int y=0;y<6;y++){Box(g,"Tablilla sellada",new Vector3(-1.18f+x*.79f,.35f+y*.55f,-.48f),new Vector3(.70f,.47f,.05f),bronze);Box(g,"Nombre inscrito",new Vector3(-1.18f+x*.79f,.35f+y*.55f,-.515f),new Vector3(.32f,.018f,.01f),glass);}Save(g);
 g=Root("Lamp");Shape(g,"Farol",Vector3.zero,new[]{new Vector2(.32f,0),new Vector2(.18f,.4f),new Vector2(.12f,2.2f),new Vector2(.35f,2.4f),new Vector2(.35f,3),new Vector2(.05f,3.25f)},bronze);Box(g,"Llama",new Vector3(0,2.7f,0),new Vector3(.36f,.5f,.36f),glow);Save(g);
 g=Root("Anvil");Shape(g,"Pedestal",Vector3.zero,new[]{new Vector2(.8f,0),new Vector2(.55f,.3f),new Vector2(.45f,.9f),new Vector2(.7f,1.1f)},stone);Box(g,"Yunque",new Vector3(0,1.25f,0),new Vector3(1.9f,.35f,.8f),iron);Shape(g,"Cuerno",new Vector3(.9f,1.25f,0),new[]{new Vector2(.25f,0),new Vector2(.03f,.7f)},iron,new Vector3(0,0,-90));Collider(g,new Vector3(2.5f,1.5f,1.5f),Vector3.up*.75f);Save(g);
 g=Root("SealWheel");Ring(g,"Rueda del juramento",Vector3.up*2,1.8f,.16f,bronze,new Vector3(90,0,0));for(int i=0;i<8;i++)Box(g,"Radio",Vector3.up*2,new Vector3(.09f,3.4f,.12f),iron,new Vector3(0,0,i*22.5f));Box(g,"Núcleo",new Vector3(0,2,0),new Vector3(.5f,.5f,.3f),glass);Save(g);
 AssetDatabase.SaveAssets();return "12 original mesh modules and five textured URP materials generated";
 }
}
